import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        long[] counts = new long[n];
        for (int i = 0; i < m; i++) counts[nextInt() - 1]++;
        long low = 0, high = 0;
        for (long c : counts) high = Math.max(high, c);
        // Binary search the finishing time T: overloaded services hand off count-T requests,
        // the others absorb floor((T-count)/2) foreign requests each.
        while (low < high) {
            long mid = (low + high) / 2, excess = 0, capacity = 0;
            for (long c : counts) {
                if (c > mid) excess += c - mid;
                else capacity += (mid - c) / 2;
            }
            if (capacity >= excess) high = mid;
            else low = mid + 1;
        }
        System.out.println(low);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n, m := readInt(), readInt()
	counts := make([]int, n)
	for i := 0; i < m; i++ {
		counts[readInt()-1]++
	}
	low, high := 0, 0
	for _, c := range counts {
		high = max(high, c)
	}
	// Binary search the finishing time T: overloaded services hand off count-T requests,
	// the others absorb floor((T-count)/2) foreign requests each.
	for low < high {
		mid := (low + high) / 2
		excess, capacity := 0, 0
		for _, c := range counts {
			if c > mid {
				excess += c - mid
			} else {
				capacity += (mid - c) / 2
			}
		}
		if capacity >= excess {
			high = mid
		} else {
			low = mid + 1
		}
	}
	fmt.Println(low)
}
